-- Generic organization tenancy for GoliathApp (one org may host many app-level customers).

CREATE SCHEMA IF NOT EXISTS portal;

CREATE TABLE IF NOT EXISTS portal."Organizations" (
  "ID" integer GENERATED BY DEFAULT AS IDENTITY NOT NULL,
  "Name" varchar(200) NOT NULL,
  "Active" boolean NOT NULL DEFAULT true,
  "CreatedAtUtc" timestamptz NOT NULL DEFAULT (now() AT TIME ZONE 'utc'),
  CONSTRAINT "PK_portal_Organizations" PRIMARY KEY ("ID")
);

CREATE TABLE IF NOT EXISTS portal."OrganizationMembers" (
  "OrganizationID" integer NOT NULL,
  "UserID" integer NOT NULL,
  "JoinedAtUtc" timestamptz NOT NULL DEFAULT (now() AT TIME ZONE 'utc'),
  CONSTRAINT "PK_portal_OrganizationMembers" PRIMARY KEY ("OrganizationID", "UserID")
);

INSERT INTO "RBAC"."Roles" ("Name", "BypassScope")
SELECT 'organization_admin', false
WHERE NOT EXISTS (
  SELECT 1 FROM "RBAC"."Roles" r WHERE r."Name" = 'organization_admin'
);

CREATE OR REPLACE FUNCTION portal.sp_organization_create(
  p_name text,
  OUT organization_id integer,
  OUT scope_id integer
)
LANGUAGE plpgsql
AS $$
BEGIN
  IF p_name IS NULL OR btrim(p_name) = '' THEN
    RAISE EXCEPTION 'name is required';
  END IF;

  INSERT INTO portal."Organizations" ("Name", "Active", "CreatedAtUtc")
  VALUES (btrim(p_name), true, now() AT TIME ZONE 'utc')
  RETURNING "ID" INTO organization_id;

  INSERT INTO "RBAC"."Scopes" (
    "ScopeType", "Name", "OrganizationID", "OwnerUserID", "Active", "CreatedAtUtc"
  )
  VALUES (
    'organization',
    btrim(p_name),
    organization_id,
    NULL,
    true,
    now() AT TIME ZONE 'utc'
  )
  RETURNING "ScopeID" INTO scope_id;
END;
$$;

CREATE OR REPLACE FUNCTION portal.sp_organization_add_member(
  p_organization_id integer,
  p_user_id integer
)
RETURNS TABLE (inserted boolean)
LANGUAGE plpgsql
AS $$
BEGIN
  IF p_organization_id IS NULL OR p_organization_id <= 0 THEN
    RAISE EXCEPTION 'organization_id is required';
  END IF;
  IF p_user_id IS NULL OR p_user_id <= 0 THEN
    RAISE EXCEPTION 'user_id is required';
  END IF;

  INSERT INTO portal."OrganizationMembers" ("OrganizationID", "UserID", "JoinedAtUtc")
  VALUES (p_organization_id, p_user_id, now() AT TIME ZONE 'utc')
  ON CONFLICT ("OrganizationID", "UserID") DO NOTHING;

  RETURN QUERY SELECT FOUND;
END;
$$;

CREATE OR REPLACE FUNCTION portal.sp_organization_set_admin(
  p_organization_id integer,
  p_user_id integer
)
RETURNS TABLE (grant_id bigint)
LANGUAGE plpgsql
AS $$
DECLARE
  v_scope_id integer;
  v_role_id integer;
  v_grant_id bigint;
BEGIN
  IF p_organization_id IS NULL OR p_organization_id <= 0 THEN
    RAISE EXCEPTION 'organization_id is required';
  END IF;
  IF p_user_id IS NULL OR p_user_id <= 0 THEN
    RAISE EXCEPTION 'user_id is required';
  END IF;

  SELECT s."ScopeID"
  INTO v_scope_id
  FROM "RBAC"."Scopes" s
  WHERE s."ScopeType" = 'organization'
    AND s."OrganizationID" = p_organization_id
    AND s."Active"
  ORDER BY s."ScopeID"
  LIMIT 1;

  IF v_scope_id IS NULL THEN
    RAISE EXCEPTION 'no active RBAC scope for organization %', p_organization_id;
  END IF;

  SELECT r."ID" INTO v_role_id
  FROM "RBAC"."Roles" r
  WHERE r."Name" = 'organization_admin';

  IF v_role_id IS NULL THEN
    RAISE EXCEPTION 'built-in role organization_admin is missing';
  END IF;

  PERFORM portal.sp_organization_add_member(p_organization_id, p_user_id);

  SELECT g."ID"
  INTO v_grant_id
  FROM "RBAC"."UserRoleGrants" g
  WHERE g."UserID" = p_user_id
    AND g."RoleID" = v_role_id
    AND g."GrantType" = 'SCOPED'
    AND g."ScopeID" = v_scope_id
    AND g."Active"
  ORDER BY g."ID"
  LIMIT 1;

  IF v_grant_id IS NULL THEN
    INSERT INTO "RBAC"."UserRoleGrants" (
      "UserID", "RoleID", "GrantType", "ScopeID", "Active", "GrantedAtUtc"
    )
    VALUES (
      p_user_id, v_role_id, 'SCOPED', v_scope_id, true, now() AT TIME ZONE 'utc'
    )
    RETURNING "ID" INTO v_grant_id;
  END IF;

  RETURN QUERY SELECT v_grant_id;
END;
$$;

CREATE OR REPLACE FUNCTION portal.sp_list_organization_members(
  p_organization_id integer
)
RETURNS TABLE (
  organization_id integer,
  user_id integer,
  full_name text,
  email text,
  joined_at_utc timestamptz
)
LANGUAGE sql
STABLE
AS $$
  SELECT
    m."OrganizationID",
    m."UserID",
    u."FullName"::text,
    u.email::text,
    m."JoinedAtUtc"
  FROM portal."OrganizationMembers" m
  INNER JOIN "RBAC"."Users" u ON u."ID" = m."UserID"
  WHERE m."OrganizationID" = p_organization_id
  ORDER BY u."FullName", u.email;
$$;
